t/api/2/issuetype/10067", "iconUrl": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": "2025-04-07T18:57:48.302-0400", "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "Hi "D", Passing this along directly to you as we have received quite a few complaints about the canned peaches. Did you ever hear back from the Warehouse about if they have been able to check the rest of the boxes? Also are you all able to connect with Emily directly about her refund request? Thank you, Alanna ---- *From:* Emily Ewing *Sent:* Sunday, February 23, 2025 8:41 AM *To:* Alanna King *Subject:* Damaged food Alanna We received a delivery of food on Tuesday, February 18. Everything was fine except for one case of peaches. 17 cans out of 24 in the case were damaged. I have pictures below. The cans with the black spots are holes where the juice leaked out. The two cans on paper had leaked and were stuck to the paper. You can see all the cans that were wet. We cannot give out food that is stained like this; plus, we have no way of knowing if the contents are bad. We could use only 7 cans from this box. Since prices are so much higher now and our money is tighter, we would like a refund. I have not heard anything about the cans of pears that were damaged a few weeks ago. Have a good week. Emily Emily Ewing West End Food Pantry. PS: ignore the last picture of drills; I donâ€™t know how to delete it! !4BDB06D6-5EFF-4BD3-A378-90169C6B3906.jpeg|thumbnail!!71D25F36-D694-4AEB-8E30-B9DD8A93806B.jpeg|thumbnail!!14A0C6D5-AFCC-4992-ABE8-E98FC87F13B0.jpeg|thumbnail!!BCB6CBB9-3158-47C8-A38C-B36BBB2C784A.jpeg|thumbnail!!E0C65F92-EE69-4D29-85F7-0ECB35BA4E0B.jpeg|thumbnail!!A88C4015-264C-4AF0-AFA3-B8E4EFB18B52.jpeg|thumbnail!!8958B738-4AB5-427C-B35D-986538387B87.jpeg|thumbnail!", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:35.298-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i009of:", "customfield_10091": null, "customfield_10092": null, "customfield_10093": null, "customfield_10094": "02:39:00", "customfield_10095": "00:23:41.700000", "customfield_10096": ["damaged-goods"], "customfield_10097": "2025-02-25", "customfield_10098": "Delivery / Pickup -> Report Issue", "customfield_10099": "Email Request", "customfield_10100": "2025-02-25 07:08:00", "customfield_10101": ["delivery-issues"], "customfield_10102": "Knnnlgi Aaa", "customfield_10103": "VA", "customfield_10104": "Partner Support / Customer Support", "customfield_10105": null, "customfield_10106": "Credit/RMA Created", "customfield_10107": "00:51:00", "customfield_10108": "C. of the R.", "customfield_10109": "English", "customfield_10110": null, "customfield_10111": "Email to Jira", "aggregatetimespent": 0, "timeoriginalestimate": 0, "aggregatetimeestimate": 0, "statuscategorychangedate": null, "aggregatetimeoriginalestimate": 0}}

