ttps://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/project/avatar/10412?size=small", "32x32": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/project/avatar/10412?size=medium", "48x48": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/project/avatar/10412"}, "simplified": true, "projectTypeKey": "business"}, "summary": "Order Modifications/Item Removals", "updated": "2025-02-26T04:37:00.000-0500", "watches": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issue/CAFBSS-726/watchers", "isWatching": false, "watchCount": 0}, "worklog": {"total": 0, "startAt": 0, "worklogs": [], "maxResults": 20}, "assignee": null, "priority": {"id": "3", "name": "Medium", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/priority/3", "iconUrl": "https://cafb-hungerbangers.atlassian.net/images/icons/priorities/medium.svg"}, "progress": {"total": 0, "progress": 0}, "reporter": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/user?accountId=712020%3A99351b4a-037f-4a38-9aea-8a927f7a32ca", "active": true, "timeZone": "America/New_York", "accountId": "712020:99351b4a-037f-4a38-9aea-8a927f7a32ca", "avatarUrls": {"16x16": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "24x24": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "32x32": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "48x48": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png"}, "accountType": "atlassian", "displayName": "Harshavardhan Patil", "emailAddress": "patil.harshavardhanc@gmail.com"}, "security": null, "subtasks": [], "versions": [], "issuetype": {"id": "10067", "name": "Story", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issuetype/10067", "iconUrl": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": null, "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "Dear Partner Support, Last Friday, 2/14/25, sale order SO194429 was delivered to our location. It included 3 bins of cereal, item 100862. At first sight, we noticed rodent droppings on top of cereal boxes in one of those bins. That bin was not accepted and the delivery driver loaded it back up inside his truck. The other two bins were b *r* ought upstairs to our storage room. To our surprise, a few minutes later, we saw a mouse coming out of one bin and returning inside that bin. We had to act quickly since other food items were stored inside this room. We immediately wrapped both bins, loaded them inside our vehicle and drove to two landfill sites to dispatch the two open bins with donated assorted cereal. Upon dispatching them, our staff saw two mice. This confirmed our fear that more than one mouse had entered inside our building and our storage room through the open bin cereals that we ordered. Of course, the issue was not over and the following Monday, 2/17/25, we caught another mouse. We will continue to closely monitor our storage room and other areas to be certain that the problem has been eradicated. Attached are pictures of what was left behind after we removed the two bins out of the storage room. This experience was very disturbing, and a solution needs to be implemented quickly. This put us behind schedule by four days due to the intervention that we put in place. We also had to throw away our products that the mice had contaminated. CAFB has been such a great partner to us and we are forever grateful for the 'all in' support that you have been providing us to allow us to help our underserved communities. That is why we are sharing this information and our experience to you so this can be further looked at and hopefully avoided. We are in this together to strengthen food security, so we know this kind of issue will be attended to and taken seriously by both parties. We look forward to your feedback or resolution around this matter. Thank you and Best regards, Anna Beavan and Jeannette Mendy Jeannette Mendy", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:28.382-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i008mn:", "customfield_10091": null, "customfield_10092": null, "customfield_10093": null, "customfield_10094": "03:00:00", "customfield_10095": "00:48:10.800000", "customfield_10096": ["item-removals"], "customfield_10097": "2025-02-25", "customfield_10098": "Delivery / Pickup -> Report Issue", "customfield_10099": "Email Request", "customfield_10100": "2025-02-25 06:58:00", "customfield_10101": ["order-modifications"], "customfield_10102": "nen.olibngomdeddirn@aunyafjto", "customfield_10103": "MD", "customfield_10104": "Partner Support / Customer 