oject/avatar/10412"}, "simplified": true, "projectTypeKey": "business"}, "summary": "Order Modifications/Item Removals", "updated": "2025-01-31T01:31:00.000-0500", "watches": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issue/CAFBSS-730/watchers", "isWatching": false, "watchCount": 0}, "worklog": {"total": 0, "startAt": 0, "worklogs": [], "maxResults": 20}, "assignee": null, "priority": {"id": "3", "name": "Medium", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/priority/3", "iconUrl": "https://cafb-hungerbangers.atlassian.net/images/icons/priorities/medium.svg"}, "progress": {"total": 0, "progress": 0}, "reporter": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/user?accountId=712020%3A99351b4a-037f-4a38-9aea-8a927f7a32ca", "active": true, "timeZone": "America/New_York", "accountId": "712020:99351b4a-037f-4a38-9aea-8a927f7a32ca", "avatarUrls": {"16x16": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "24x24": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "32x32": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png", "48x48": "https://secure.gravatar.com/avatar/d81d196ead1002318c72684d9ece0e10?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FHP-0.png"}, "accountType": "atlassian", "displayName": "Harshavardhan Patil", "emailAddress": "patil.harshavardhanc@gmail.com"}, "security": null, "subtasks": [], "versions": [], "issuetype": {"id": "10067", "name": "Story", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issuetype/10067", "iconUrl": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": null, "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "Hello, I received this e-mail below on Friday evening, 1/24/25, that informed me of the removal of item 520059 from sale order SO191436. However I found it again available to order, same quantity, on Sunday evening, 1/26/25. I added it again, same quantity, to my next order SO191941. Could you please let me know why it was removed from my order? Could you guarantee that the item is available and it won't be remove again from SO191941? !image.png|thumbnail! ---- *From:* partner Support (partnersupport@capitalareafoodbank.org) *Sent:* Friday, January 24, 2025 8:04 PM *To:* Jeannette Mendy *Subject:* Change in Your Upcoming Sales Order Dear Valued Partner, We regret to inform you that we had to remove or reduce the quantity of item(s) from your order *SO191436*. Below is a list of item(s) and reason for the change. We understand that this change may cause inconvenience to you and your distribution plans, and we apologize for the inconvenience. Please note that if you are receiving this notification after your order has been locked, which is three business days before your order is due to be picked up or delivered, this change is most likely occurring during or after the pulling stage and unfortunately, we cannot replace the item removed or make any further additions during this time period. ||Item ||Reason for Change | |520059 MD TEFAP BON Catfish Fillets Unbrd Raw FRZN |Ran Out of Product | |520483 MD TEFAP CHEESE CHED YEL CHUNKS-PKG 12/2 LB |Line Not Fulfilled in WH | To review an updated version of your order, please log in to PartnerLink and visit the Order History tab. If you have any queries or concerns, please do not hesitate to contact us at Thank you for your understanding and continued support. Best regards, Partner Support", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:36.636-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i00adz:", "customfield_10091": null, "customfield_10092": "SO191436", "customfield_10093": null, "customfield_10094": "01:34:00", "customfield_10095": "00:48:51.100000", "customfield_10096": ["item-removals"], "customfield_10097": "2025-01-27", "customfield_10098": "Menu -> Inventory Availability", "customfield_10099": "Email Request", "customfield_10100": "2025-01-27 02:51:00", "customfield_10101": ["order-modifications"], "customfield_10102": "ecietuis@nny..ovsmstatteesm-", "customfield_10103": "MD", "customfield_10104": "Partner Support / Customer Support", "customfield_10105": null, "customfield_10106": "Question Answered", "customfield_10107": "10:08:00", "customfield_10108": "L. F.", "customfield_10109": "English", "customfield_10110": null, "customfield_10111": "Email to Jira", "aggregatetimespent": 0, "timeoriginalestimate": 0, "aggregatetimeestimate": 0, "statuscategorychangedate": null, "aggregatetimeoriginalestimate": 0}}

{"id": "11806", "key": "CAFBSS-929", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issue/11806", "expand": "operations,versionedRepresentations,editmeta,changelog,renderedFields", "fields": {"votes": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issue/CAFBSS-929/votes", "votes": 0, "hasVoted": false}, "labels": [], "status": {"id": "10102", "name": "Closed", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/status/10102", "iconUrl": "https://cafb-hungerbangers.atlassian.net/", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}}, "comment": {"self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issue/11806/comment", "total": 1, "startAt": 0, "comments": [{"id": "11940", "body": "01/28/2025 01:31;61536ea272f6970069fc1dbd;Good afternoon, Mr. Oliver,

I hope this message finds you well. Thank you for bringing this to our attention! I have discussed this matter with our leadership and the team involved in this initiative. We appreciate you reopening the discussion.

When we initiated this plan, our goal was to alleviate the burden on our Tuesday schedule due to the number of large deliveries we have on that day. However, we acknowledge the challenges this has caused for your agency, which was not our intended outcome. Letâ€™s work together to find a solution!

One option I wanted to explore with you is whether you would be open to either receiving all your food items on Fridays or accepting deliveries on Mondays instead of Tuesdays. Please let me know your preference, and if neither option works for you, I will take that information back to our department leaders and Operations for further consideration. Our aim is to ensure that we do not burden your distribution or volunteers.

Thank you, Pastor Oliver!

Best regards,  
"D"
02/03/2025 12:02;61536ea272f6970069fc1dbd;Good morning Mr. Oliver, just checking in here to see if you saw my response. 
