suetype": {"id": "10067", "name": "Story", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/issuetype/10067", "iconUrl": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": null, "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "Good Morning, A few months ago, we were contacted about switching our distribution day from Tuesday to a later day in the week, and we agreed to move it to Wednesday. However, weâ€™ve found that having only one day between our distribution dates has been challenging for our volunteers and has created scheduling conflicts with some of our other pickups. Now that the holidays are over, weâ€™d like to request switching back to our original Tuesday distribution. This change would allow us to serve the community more effectively and provide our volunteers with adequate time to recover between distributions. We understand the importance of aligning with your delivery schedule and want to remain considerate of your operations. However, we would greatly appreciate it if this adjustment could be made. Please let us know if this is possible. Looking forward to hearing from you. Best regards, Oliver", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:37.253-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i00aqf:", "customfield_10091": null, "customfield_10092": null, "customfield_10093": null, "customfield_10094": "02:59:00", "customfield_10095": "00:31:44.700000", "customfield_10096": ["rescheduling-pickup"], "customfield_10097": "2025-02-04", "customfield_10098": "Delivery / Pickup -> General Questions", "customfield_10099": "Email Request", "customfield_10100": "2025-02-04 10:47:00", "customfield_10101": ["pickup-scheduling-&-rescheduling"], "customfield_10102": "ioa@cloclr.tsuahigtmiomenm", "customfield_10103": "MD", "customfield_10104": "Partner Support / Customer Support", "customfield_10105": null, "customfield_10106": "Question Answered", "customfield_10107": "09:12:00", "customfield_10108": "No L. O.", "customfield_10109": "English", "customfield_10110": null, "customfield_10111": "Email to Jira", "aggregatetimespent": 0, "timeoriginalestimate": 0, "aggregatetimeestimate": 0, "statuscategorychangedate": null, "aggregatetimeoriginalestimate": 0}}

