/rest/api/2/issuetype/10067", "iconUrl": "https://cafb-hungerbangers.atlassian.net/rest/api/2/universal_avatar/view/type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": null, "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "---- *From:* Than Tran *Sent:* Monday, November 25, 2024 10:06:59 AM *To:* Alanna King *Cc:* MaiTam Nguyen *Subject:* BPSOS - Food Order Issue Hello Alanna, Happy Monday! This is Than from BPSOS. I am writing this because we encountered a technical issue on the website. Last Friday 11/22, we tried to add a few items, namely 2 of the *800908 Cabbage, Green Local 675# BIN 1/675 lbs Bin* into our cart, to be delivered this Wednesday 11/27. However, it said that those items were not available on that selected date, but in the item description, it said that it will still be available until 12/10. As a result, we could not select those items back then. It was pretty late then, so I was not able to email you until today. I know that we may past the deadline for edit order; however, is it possible for you to remove all of the "300597 Turkey Breast, 6-9# Basted w/ Gravy Packet 1/30.42486 lbs Case" from our cart, and replace them with 2 of the "800908 Cabbage, Green Local 675# BIN 1/675 lbs Bin?" Additionally, do we still need to order more than 1000 lbs to be eligible for delivery? I know that we are asking a lot Alanna, but we want to make sure that our vulnerable and underserved population can enjoy a good Thanksgiving this week. We would appreciate a lot if you can help us. Best,", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:36.642-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i00b1z:", "customfield_10091": null, "customfield_10092": null, "customfield_10093": null, "customfield_10094": "02:25:00", "customfield_10095": "00:41:40.500000", "customfield_10096": ["item-removals"], "customfield_10097": "2024-11-25", "customfield_10098": "Orders - Pre delivery -> Edit Order Items", "customfield_10099": "Email Request", "customfield_10100": "2024-11-25 02:21:00", "customfield_10101": ["order-modifications"], "customfield_10102": "lna KiAanng", "customfield_10103": "VA", "customfield_10104": "Partner Support / Customer Support", "customfield_10105": null, "customfield_10106": "Order Updated", "customfield_10107": "12:19:00", "customfield_10108": "B. P. SOS", "customfield_10109": "English", "customfield_10110": null, "customfield_10111": "Email to Jira", "aggregatetimespent": 0, "timeoriginalestimate": 0, "aggregatetimeestimate": 0, "statuscategorychangedate": null, "aggregatetimeoriginalestimate": 0}}

