type/issuetype/avatar/10315?size=medium", "subtask": false, "avatarId": 10315, "entityId": "683abcaf-4b9b-46b1-969d-39a9d109d909", "description": "(Migrated on 5 Apr 2025 15:04 UTC)", "hierarchyLevel": 0}, "timespent": 0, "workratio": -1, "attachment": [], "components": [], "issuelinks": [], "lastViewed": null, "resolution": {"id": "10000", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/resolution/10000", "description": "Work has been completed on this issue."}, "description": "Hi Partner Support, I hope you are doing well. Yesterday, my team went on a site visit to Greater Refuge Ministries in MD. They let us know that they have frequently had late deliveries during the day of their distribution and that they have received rotten and moldy produce, specifically cantaloupes. We informed them to send photographs of rotten produce and to let your team know right away if it happens again. Please let me know if you have any questions. Thank you! Best, Grace", "environment": null, "fixVersions": [], "timeestimate": 0, "timetracking": {"timeSpent": "0m", "originalEstimate": "0m", "timeSpentSeconds": 0, "remainingEstimate": "0m", "originalEstimateSeconds": 0, "remainingEstimateSeconds": 0}, "resolutiondate": "2025-04-05T11:05:38.213-0400", "statusCategory": {"id": 3, "key": "done", "name": "Done", "self": "https://cafb-hungerbangers.atlassian.net/rest/api/2/statuscategory/3", "colorName": "green"}, "aggregateprogress": {"total": 0, "progress": 0}, "customfield_10015": null, "customfield_10019": "0|i00btz:", "customfield_10091": null, "customfield_10092": null, "customfield_10093": null, "customfield_10094": "02:50:00", "customfield_10095": "00:35:59.700000", "customfield_10096": ["late-deliveries"], "customfield_10097": "2024-09-12", "customfield_10098": "Feedback - Concern / Negative -> Quality - Produce", "customfield_10099": "Email Request", "customfield_10100": "2024-09-12 08:36:00", "customfield_10101": ["delivery-issues"], "customfield_1